-- Grace days: when the sheet's today is changed, every open period whose to-date plus them is before
-- the new today closes itself; null for off.
ALTER TABLE sheet ADD COLUMN grace_days INT;
-- The review SLA in days: a REVIEW claim whose review day (the sheet's today when it went to REVIEW)
-- plus them is before the sheet's today is late. Null means none; not dated.
ALTER TABLE sheet ADD COLUMN review_sla INT;
-- The grade the quick-add bar and a blank-graded import line give a new person: A, B or C; null for A. Not dated.
ALTER TABLE sheet ADD COLUMN default_grade VARCHAR(1);
